create table public.analytics_events(id bigint generated always as identity primary key,user_id uuid references auth.users(id) on delete set null,anonymous_id_hash text,event_name text not null,path text,properties jsonb not null default '{}',occurred_at timestamptz not null,received_at timestamptz not null default now(),check(jsonb_typeof(properties)='object'));
create table public.operational_errors(id bigint generated always as identity primary key,service text not null,error_code text not null,route text,severity text not null check(severity in ('info','warning','error','critical')),request_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.ai_request_audits(id bigint generated always as identity primary key,user_id uuid references auth.users(id) on delete set null,prompt_key text not null,prompt_version text not null,model_key text not null,request_id text not null unique,input_tokens integer,output_tokens integer,latency_ms integer,status text not null check(status in ('success','refused','failed','rate_limited')),safety_flags text[] not null default '{}',created_at timestamptz not null default now());
alter table public.analytics_events enable row level security;alter table public.operational_errors enable row level security;alter table public.ai_request_audits enable row level security;create policy "users insert bounded analytics" on public.analytics_events for insert with check(user_id is null or user_id=auth.uid());create policy "staff read analytics" on public.analytics_events for select using(public.is_platform_staff());create policy "staff read operational errors" on public.operational_errors for select using(public.is_platform_staff());create policy "users read own ai audits" on public.ai_request_audits for select using(user_id=auth.uid());create index analytics_event_time_idx on public.analytics_events(event_name,occurred_at desc);create index errors_service_time_idx on public.operational_errors(service,created_at desc);create index ai_audit_user_time_idx on public.ai_request_audits(user_id,created_at desc);
